package com.wizzadrds.theworldremembers.inventory; import com.mojang.serialization.Codec; import net.minecraft.server.level.ServerLevel; import net.minecraft.resources.Identifier; import net.minecraft.world.level.saveddata.*; import java.util.*; public final class NpcEquipmentManager extends SavedData{private final Map<UUID,NpcEquipmentState> states=new HashMap<>();private static final Codec<NpcEquipmentManager> CODEC=Codec.unboundedMap(Codec.STRING.xmap(UUID::fromString,UUID::toString),NpcEquipmentState.CODEC).xmap(m->{var x=new NpcEquipmentManager();x.states.putAll(m);return x;},x->x.states);private static final SavedDataType<NpcEquipmentManager> TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath("the_world_remembers","equipment"),NpcEquipmentManager::new,CODEC,null);public static NpcEquipmentManager get(ServerLevel w){return w.getDataStorage().computeIfAbsent(TYPE);}public void sync(UUID id,String item){var n=new NpcEquipmentState(item);if(!n.equals(states.get(id))){states.put(id,n);setDirty();}}public NpcEquipmentState get(UUID id){return states.get(id);}}
